{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Rufinamide absolute oral bioavailability is 85% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C77"],
      "claim": "Niraparib absolute oral bioavailability is 72.7% (90% CI 61.69–83.40) after a 300 mg oral dose in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Didanosine absolute oral bioavailability is 42% ± 12% from a chewable tablet in patients with normal renal function, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-assay-transfer evidence molecules show direct absolute oral bioavailability values well above 20%, including 85%, 72.7%, and 42%. Sub-20% values appear only in altered conditions or inconsistent provenance groups and do not outweigh the direct absolute measurements.",
  "evidence_gaps": [
    "Molecule 3 and Molecule 6 contain records for different compounds under one label; those inconsistent cards were discounted.",
    "Some didanosine records report F below 20% under fed conditions or in children; these altered-condition records were discounted relative to the absolute adult measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

